A = (1,0);
B = rotate(60)*A;
C=rotate(60)*B;
D = rotate(60)*C;
EE = rotate(60)*D;
F = rotate(60)*EE;

P = A + (A - B);
draw (A--B--C--D--EE--F--A--P--F,linewidth(1));
label("$A$",A,NE);
label("$B$",B,N);
label("$C$",C,N);
